-- Add the editable general Controls text to the canonical JSA PDF.
-- Only untouched built-in documents match both exact source and compiled HTML.
-- Tenant-authored or customized layouts are deliberately preserved.
DO $migration$
DECLARE tenant_row record;
BEGIN
  FOR tenant_row IN SELECT id FROM tenants LOOP
    PERFORM set_config('app.tenant_id', tenant_row.id::text, true);
    UPDATE pdf_templates
    SET source_html = $template$<div style="font-family:-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#0f172a;"><div style="border-bottom:3px solid #0f172a;padding-bottom:8px;margin-bottom:10px;"><table style="width:100%;border-collapse:collapse;"><tr><td style="border:none;padding:0;"><h1 style="font-size:21px;font-weight:800;color:#0f172a;margin:0;letter-spacing:.2px;">Hazard Assessment</h1><p style="font-size:12px;color:#64748b;margin:3px 0 0;">{{type_name}}</p></td><td style="border:none;padding:0;text-align:right;font-size:12px;color:#475569;vertical-align:top;">Reference <strong>{{reference}}</strong></td></tr></table></div><div style="margin:0 0 10px;"><span style="display:inline-block;border:1px solid #cbd5e1;background:#f1f5f9;color:#334155;border-radius:999px;padding:2px 10px;font-size:10px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;margin:0 6px 4px 0;">{{status_label}}</span><span style="display:inline-block;border:1px solid #cbd5e1;background:#f1f5f9;color:#334155;border-radius:999px;padding:2px 10px;font-size:10px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;margin:0 6px 4px 0;">{{type_name}}</span></div><table style="width:100%;border-collapse:collapse;"><tr><td style="border:none;padding:14px 0 6px;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;">General information</div></td></tr></table><table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 10px;"><tr style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Occurred</td><td style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{occurred_at}}</td><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Location</td><td style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{site_name}}</td></tr><tr style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Specific location</td><td style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{location_on_site}}</td><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Project</td><td style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{project_name}}</td></tr><tr style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Supervisor</td><td style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{supervisor_name}}</td><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Completed by</td><td style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{reported_by_name}}</td></tr><tr data-if="locked_at" style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Locked at</td><td colspan="3" style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{locked_at}}</td></tr></table><table style="width:100%;border-collapse:collapse;margin:0 0 10px;"><tr data-if="job_scope" style="page-break-inside:auto;"><td style="border:none;padding:12px 0 0;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;break-after:avoid;page-break-after:avoid;">Job scope</div><div style="border:1px solid #e2e8f0;border-left:3px solid #0f172a;background:#f8fafc;padding:8px 10px;font-size:11.5px;color:#0f172a;line-height:1.55;white-space:pre-wrap;margin-top:6px;">{{job_scope}}</div></td></tr></table><table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 10px;"><colgroup><col style="width:4%" /><col style="width:30%" /><col style="width:66%" /></colgroup><thead><tr data-if="tasks"><td colspan="3" style="border:none;padding:14px 0 6px;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;">Tasks</div></td></tr><tr data-if="tasks"><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:4%;">#</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:30%;">Task</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Controls</th></tr></thead><tr data-each="tasks" style="page-break-inside:avoid;"><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:4%;">{{@number}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:30%;">{{name}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{controls}}</td></tr></table>{{#if show_risk_ratings}}<table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 10px;"><colgroup><col style="width:4%" /><col style="width:24%" /><col style="width:24%" /><col style="width:24%" /><col style="width:9%" /><col style="width:9%" /><col style="width:6%" /></colgroup><thead><tr data-if="hazards"><td colspan="7" style="border:none;padding:14px 0 6px;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;">Hazards & controls</div></td></tr><tr data-if="hazards"><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:4%;">#</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Hazard</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Standard controls</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Specific controls</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:9%;">Pre L/S (risk)</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:9%;">Post L/S (risk)</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:6%;">Applies</th></tr></thead><tr data-each="hazards" style="page-break-inside:avoid;"><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:4%;">{{@number}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{name}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{standard_controls}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{specific_controls}}{{#if controls}}<div style="margin-top:4px;"><strong>Controls:</strong> {{controls}}</div>{{/if}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:9%;">{{pre_likelihood}} / {{pre_severity}} ({{pre_risk}})</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:9%;">{{post_likelihood}} / {{post_severity}} ({{post_risk}})</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:6%;">{{applicable}}</td></tr></table>{{else}}<table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 10px;"><colgroup><col style="width:4%" /><col style="width:29.333333333333332%" /><col style="width:8%" /><col style="width:29.333333333333332%" /><col style="width:29.333333333333332%" /></colgroup><thead><tr data-if="hazards"><td colspan="5" style="border:none;padding:14px 0 6px;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;">Hazards & controls</div></td></tr><tr data-if="hazards"><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:4%;">#</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Hazard</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:8%;">Applies</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Standard controls</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Specific controls</th></tr></thead><tr data-each="hazards" style="page-break-inside:avoid;"><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:4%;">{{@number}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{name}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:8%;">{{applicable}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{standard_controls}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{specific_controls}}{{#if controls}}<div style="margin-top:4px;"><strong>Controls:</strong> {{controls}}</div>{{/if}}</td></tr></table>{{/if}}<table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 10px;"><colgroup><col style="width:22%" /><col style="width:58%" /><col style="width:10%" /><col style="width:10%" /></colgroup><thead><tr data-if="ppe"><td colspan="4" style="border:none;padding:14px 0 6px;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;">PPE manifest</div></td></tr><tr data-if="ppe"><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:22%;">PPE</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Description</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:10%;">Required</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:10%;">Answer</th></tr></thead><tr data-each="ppe" style="page-break-inside:avoid;"><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:22%;">{{name}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{description}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:10%;">{{required}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:10%;">{{answer}}</td></tr></table><table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 10px;"><colgroup><col style="width:4%" /><col style="width:71%" /><col style="width:14%" /><col style="width:11%" /></colgroup><thead><tr data-if="questions"><td colspan="4" style="border:none;padding:14px 0 6px;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;">Questions & answers</div></td></tr><tr data-if="questions"><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:4%;">#</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Question</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:14%;">Answer</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:11%;">Requires yes</th></tr></thead><tr data-each="questions" style="page-break-inside:avoid;"><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:4%;">{{@number}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{question}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:14%;">{{answer}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:11%;">{{requires_yes}}</td></tr></table><table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 10px;"><colgroup><col style="width:30%" /><col style="width:12%" /><col style="width:8%" /><col style="width:8%" /><col style="width:8%" /><col style="width:20%" /><col style="width:14%" /></colgroup><thead><tr data-if="signatures"><td colspan="7" style="border:none;padding:14px 0 6px;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;">Signatures</div></td></tr><tr data-if="signatures"><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Name</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:12%;">Type</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:8%;">Entrant</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:8%;">Attendant</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:8%;">Rescue</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:20%;">Signature</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:14%;">Signed</th></tr></thead><tr data-each="signatures" style="page-break-inside:avoid;"><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{name}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:12%;">{{type}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:8%;">{{cs_entrant}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:8%;">{{cs_attendant}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:8%;">{{cs_rescue}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:20%;">{{#if image}}<img src="{{image}}" style="max-height:44px;display:block;" alt="" />{{/if}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:14%;">{{signed_at}}</td></tr></table>{{#if photos}}<div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;margin:14px 0 8px;break-after:avoid;page-break-after:avoid;">Photos</div>
    <div style="font-size:0;">{{#each photos}}<div style="display:inline-block;vertical-align:top;width:48%;margin:0 2% 10px 0;page-break-inside:avoid;">
      <img src="{{url}}" style="display:block;width:100%;height:210px;object-fit:contain;border:1px solid #e2e8f0;" alt="" />
