ont-size:11.5px;color:#0f172a;vertical-align:top;width:20%;">{{#if image}}<img src="{{image}}" style="max-height:44px;display:block;" alt="" />{{/if}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:14%;">{{signed_at}}</td></tr>{{/each}}</table>{{#if photos}}<div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;margin:14px 0 8px;break-after:avoid;page-break-after:avoid;">Photos</div>
